import { hashPassword, verifyPassword } from './password';

describe('password', () => {
  it('verifies the right password', async () => {
    const stored = await hashPassword('correct horse battery');
    await expect(verifyPassword('correct horse battery', stored)).resolves.toBe(
      true,
    );
  });

  it('rejects a wrong password', async () => {
    const stored = await hashPassword('correct horse battery');
    await expect(verifyPassword('wrong horse battery', stored)).resolves.toBe(
      false,
    );
  });

  it('returns false for a malformed stored value', async () => {
    const stored = await hashPassword('correct horse battery');
    const [, , , , salt, hash] = stored.split('$');
    const malformed = [
      '',
      'not-a-hash',
      `bcrypt$16384$8$1$${salt}$${hash}`,
      `scrypt$16384$8$1$${salt}`,
      `scrypt$16384$8$1$${salt}$${hash}$extra`,
      `scrypt$abc$8$1$${salt}$${hash}`,
      // scrypt throws for an N that is not a power of two.
      `scrypt$16383$8$1$${salt}$${hash}`,
      `scrypt$16384$8$1$${salt}$${hash.slice(0, 20)}`,
      `scrypt$16384$8$1$${salt}$not+base64url`,
    ];
    for (const value of malformed) {
      await expect(
        verifyPassword('correct horse battery', value),
        value,
      ).resolves.toBe(false);
    }
  });

  it('produces a different hash each time for the same password', async () => {
    const first = await hashPassword('correct horse battery');
    const second = await hashPassword('correct horse battery');
    expect(first).not.toBe(second);
    await expect(verifyPassword('correct horse battery', second)).resolves.toBe(
      true,
    );
  });
});

import { randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { parseEnv } from 'node:util';
import { loadConfig } from './config';

const example = parseEnv(
  readFileSync(resolve(import.meta.dirname, '../../../.env.example'), 'utf8'),
);
const validSecret = randomBytes(36).toString('base64url');

function exampleWith(overrides: Record<string, string>) {
  return { ...example, JWT_SECRET: validSecret, ...overrides };
}

function configError(env: Record<string, string | undefined>): string {
  try {
    loadConfig(env);
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
  throw new Error('loadConfig accepted the configuration');
}

describe('loadConfig', () => {
  it('accepts the values in .env.example with a valid 48-character secret', () => {
    expect(validSecret).toHaveLength(48);
    const config = loadConfig(exampleWith({}));
    expect(config.PORT).toBe(3000);
    expect(config.SLACK_WEBHOOK_ALLOWED_PREFIXES).toEqual([
      'https://hooks.slack.com/services/',
      'http://localhost:3000/api/dev/mock-slack/',
    ]);
  });

  it('rejects the placeholder secret from .env.example', () => {
    const message = configError(example);
    expect(message).toContain('JWT_SECRET');
    expect(message).not.toContain(example.JWT_SECRET);
  });

  it('rejects a 31-character secret', () => {
    const shortSecret = validSecret.slice(0, 31);
    const message = configError(exampleWith({ JWT_SECRET: shortSecret }));
    expect(message).toContain('JWT_SECRET: must be at least 32 characters');
    expect(message).not.toContain(shortSecret);
  });

  it('rejects a Slack prefix without a trailing slash', () => {
    const message = configError(
      exampleWith({
        SLACK_WEBHOOK_ALLOWED_PREFIXES: 'https://hooks.slack.com/services',
      }),
    );
    expect(message).toContain(
      'SLACK_WEBHOOK_ALLOWED_PREFIXES: entry 1 must end with "/"',
    );
  });

  it('rejects a Slack prefix with a username', () => {
    const message = configError(
      exampleWith({
        SLACK_WEBHOOK_ALLOWED_PREFIXES:
          'https://hookuser@hooks.slack.com/services/',
      }),
    );
    expect(message).toContain(
      'SLACK_WEBHOOK_ALLOWED_PREFIXES: entry 1 must not contain a username or password',
    );
    expect(message).not.toContain('hookuser');
  });

  it('rejects an http: Slack prefix when NODE_ENV is production', () => {
    const message = configError(exampleWith({ NODE_ENV: 'production' }));
    expect(message).toContain(
      'SLACK_WEBHOOK_ALLOWED_PREFIXES: entry 2 uses http:',
    );
    expect(() =>
      loadConfig(
        exampleWith({
          NODE_ENV: 'production',
          SLACK_WEBHOOK_ALLOWED_PREFIXES: 'https://hooks.slack.com/services/',
        }),
      ),
    ).not.toThrow();
  });
});

import { randomBytes, randomUUID } from 'node:crypto';
import { eq, inArray } from 'drizzle-orm';
import type { FastifyInstance, LightMyRequestResponse } from 'fastify';
import type { Pool } from 'pg';
import { buildApp } from '../app';
import { loadConfig } from '../config';
import { createDb, type Db } from '../db/client';
import { users } from '../db/schema';
import { createSessionTokens, SESSION_COOKIE } from './session';

const password = 'correct horse battery';

describe('auth routes', () => {
  let app: FastifyInstance;
  let db: Db;
  let pool: Pool;
  let createdEmails: string[] = [];

  beforeAll(async () => {
    const config = loadConfig({ ...process.env, AUTH_RATE_LIMIT_MAX: '1000' });
    ({ db, pool } = createDb(config.TEST_DATABASE_URL));
    app = await buildApp(config, { db });
    await app.ready();
  });

  afterEach(async () => {
    if (createdEmails.length > 0) {
      await db.delete(users).where(inArray(users.email, createdEmails));
    }
    createdEmails = [];
  });

  afterAll(async () => {
    await app?.close();
    await pool?.end();
  });

  function newEmail(): string {
    const email = `auth-test-${randomUUID()}@example.com`;
    createdEmails.push(email);
    return email;
  }

  function register(email: string): Promise<LightMyRequestResponse> {
    return app.inject({
      method: 'POST',
      url: '/api/auth/register',
      payload: { email, password },
    });
  }

  function login(
    email: string,
    loginPassword: string,
  ): Promise<LightMyRequestResponse> {
    return app.inject({
      method: 'POST',
      url: '/api/auth/login',
      payload: { email, password: loginPassword },
    });
  }

  function me(session: string): Promise<LightMyRequestResponse> {
    return app.inject({
      method: 'GET',
      url: '/api/auth/me',
      cookies: { [SESSION_COOKIE]: session },
    });
  }

  function sessionCookie(response: LightMyRequestResponse) {
    const cookie = response.cookies.find(
      (candidate) => candidate.name === SESSION_COOKIE,
    );
    if (!cookie) {
      throw new Error('The response set no session cookie');
    }
    return cookie;
  }

  it('register then me returns 200 with the user', async () => {
    const email = newEmail();
    const registered = await register(email);
    expect(registered.statusCode).toBe(201);

    const response = await me(sessionCookie(registered).value);
    expect(response.statusCode).toBe(200);
    expect(response.json()).toEqual({
      id: registered.json().id,
      email,
      role: 'user',
    });
  });

  it('a duplicate register returns 409', async () => {
    const email = newEmail();
    expect((await register(email)).statusCode).toBe(201);

    const duplicate = await register(email);
    expect(duplicate.statusCode).toBe(409);
    expect(duplicate.cookies).toEqual([]);
  });

  it('login with a wrong password returns 401', async () => {
    const email = newEmail();
    expect((await register(email)).statusCode).toBe(201);

    const wrong = await login(email, 'wrong horse battery');
    expect(wrong.statusCode).toBe(401);
    expect(wrong.cookies).toEqual([]);
    expect((await login(email, password)).statusCode).toBe(200);
  });

  it('logout then me returns 401', async () => {
    const email = newEmail();
    const session = sessionCookie(await register(email)).value;

    const logout = await app.inject({
      method: 'POST',
      url: '/api/auth/logout',
      cookies: { [SESSION_COOKIE]: session },
    });
    expect(logout.statusCode).toBe(204);
    const cleared = sessionCookie(logout);
    expect(cleared.value).toBe('');
    expect(cleared.path).toBe('/');
    expect(cleared.expires?.getTime()).toBeLessThanOrEqual(Date.now());

    expect((await me(cleared.value)).statusCode).toBe(401);
  });

  it('a session cookie signed with another secret returns 401', async () => {
    const email = newEmail();
    const registered = await register(email);
    expect(registered.statusCode).toBe(201);

    const otherTokens = createSessionTokens(
      randomBytes(36).toString('base64url'),
    );
    const forged = await otherTokens.sign({
      id: registered.json().id,
      role: 'user',
    });
    expect((await me(forged)).statusCode).toBe(401);
  });

  it('a user whose row was deleted returns 401', async () => {
    const email = newEmail();
    const session = sessionCookie(await register(email)).value;
    expect((await me(session)).statusCode).toBe(200);

    await db.delete(users).where(eq(users.email, email));
    expect((await me(session)).statusCode).toBe(401);
  });

  it('a request with Content-Type text/plain returns 415', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/api/auth/login',
      headers: { 'content-type': 'text/plain' },
      payload: JSON.stringify({ email: 'nobody@example.com', password }),
    });
    expect(response.statusCode).toBe(415);
  });
});

