import { and, eq, lte } from 'drizzle-orm';
import type { Db } from '../db/client';
import {
  alerts,
  alertTargets,
  channels,
  deliveries,
  events,
  targets,
} from '../db/schema';
import {
  matchesFilters,
  type MatchAlert,
  type MatchEvent,
} from '../matching/match';
import type { NewEvent } from '../sources/source';

type Tx = Parameters<Parameters<Db['transaction']>[0]>[0];
type DeliveryInsert = typeof deliveries.$inferInsert;

export type EventRow = typeof events.$inferSelect;

export interface IngestResult {
  event: EventRow;
  deliveriesCreated: number;
}

// Returns the number of delivery rows inserted. Rows that already exist are left alone (R9).
export async function matchEvent(tx: Tx, event: EventRow): Promise<number> {
  const candidates = await tx
    .select({
      alertId: alerts.id,
      category: alerts.category,
      minSeverity: alerts.minSeverity,
      filters: alerts.filters,
      targetId: targets.id,
      channel: targets.channel,
    })
    .from(alerts)
    .innerJoin(alertTargets, eq(alertTargets.alertId, alerts.id))
    .innerJoin(targets, eq(targets.id, alertTargets.targetId))
    .where(
      and(
        eq(alerts.enabled, true),
        eq(alerts.category, event.category),
        lte(alerts.minSeverity, event.severity),
      ),
    )
    // A concurrent alert or target delete waits, so the delivery insert never hits a missing row.
    .for('key share', { of: [alerts, targets] });

  // Ingest and the alert routes validated category with data and filters, which the column types cannot express.
  const matched = candidates.filter((row) =>
    matchesFilters(event as MatchEvent, row as MatchAlert),
  );
  if (matched.length === 0) {
    return 0;
  }

  const enabledChannels = new Set(
    (
      await tx
        .select({ id: channels.id })
        .from(channels)
        .where(eq(channels.enabled, true))
    ).map((row) => row.id),
  );
  const rows = matched.map(
    ({ alertId, targetId, channel }): DeliveryInsert => {
      const enabled = enabledChannels.has(channel);
      return {
        alertId,
        eventId: event.id,
        targetId,
        channel,
        status: enabled ? 'pending' : 'skipped',
        attempts: 0,
        lastError: enabled ? null : 'channel disabled',
      };
    },
  );
  const inserted = await tx
    .insert(deliveries)
    .values(rows)
    .onConflictDoNothing({
      target: [deliveries.alertId, deliveries.eventId, deliveries.targetId],
    })
    .returning({ id: deliveries.id });
  return inserted.length;
}

// Returns null when the source already delivered an event with this externalId.
export async function ingestEvent(
  db: Db,
  event: NewEvent,
): Promise<IngestResult | null> {
  return db.transaction(async (tx) => {
    const [stored] = await tx
      .insert(events)
      .values({
        sourceId: event.sourceId,
        externalId: event.externalId,
        category: event.category,
        title: event.title,
        summary: event.summary,
        severity: event.severity,
        data: event.data,
        occurredAt: event.occurredAt ? new Date(event.occurredAt) : new Date(),
      })
      .onConflictDoNothing({ target: [events.sourceId, events.externalId] })
      .returning();
    if (!stored) {
      return null;
    }
    return { event: stored, deliveriesCreated: await matchEvent(tx, stored) };
  });
}

import { eq } from 'drizzle-orm';
import type { FastifyBaseLogger } from 'fastify';
import type { Db } from '../db/client';
import { sources } from '../db/schema';
import { ingestEvent } from '../events/ingest';
import type { EventSource, NewEvent } from './source';

export interface SchedulerDeps {
  db: Db;
  sources: readonly EventSource[];
  log: Pick<FastifyBaseLogger, 'error'>;
  ingest?: (db: Db, event: NewEvent) => Promise<unknown>;
}

// A source without a row was never registered, so it counts as disabled.
async function isEnabled(db: Db, sourceId: string): Promise<boolean> {
  const [row] = await db
    .select({ enabled: sources.enabled })
    .from(sources)
    .where(eq(sources.id, sourceId))
    .limit(1);
  return row?.enabled ?? false;
}

// The returned stop function resolves once no poll is running.
export function startScheduler(deps: SchedulerDeps): () => Promise<void> {
  const { db, log, ingest = ingestEvent } = deps;
  const timers = new Set<ReturnType<typeof setTimeout>>();
  const running = new Set<Promise<void>>();
  let stopped = false;

  async function tick(source: EventSource): Promise<void> {
    try {
      if (!(await isEnabled(db, source.id))) {
        return;
      }
      for (const event of await source.poll()) {
        await ingest(db, event);
      }
    } catch (error) {
      log.error({ err: error, sourceId: source.id }, 'Source poll failed');
    }
  }

  function schedule(source: EventSource): void {
    if (stopped) {
      return;
    }
    const timer = setTimeout(() => {
      timers.delete(timer);
      const run = tick(source).finally(() => {
        running.delete(run);
        schedule(source);
      });
      running.add(run);
    }, source.nextDelayMs());
    timers.add(timer);
  }

  deps.sources.forEach(schedule);

  return async () => {
    stopped = true;
    timers.forEach(clearTimeout);
    timers.clear();
    await Promise.all(running);
  };
}

