import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { computed, inject, Injectable, signal } from '@angular/core';
import type { LoginInput, RegisterInput, UserDto } from '@alerts/shared';
import { firstValueFrom } from 'rxjs';

export const ME_URL = '/api/auth/me';

@Injectable({ providedIn: 'root' })
export class AuthStore {
  private readonly http = inject(HttpClient);
  private readonly _user = signal<UserDto | null>(null);
  private request: Promise<UserDto | null> | null = null;

  readonly user = this._user.asReadonly();
  readonly isAdmin = computed(() => this._user()?.role === 'admin');

  // Calls GET /api/auth/me on first use only. Errors other than 401 are not cached, so the next call retries.
  load(): Promise<UserDto | null> {
    this.request ??= firstValueFrom(this.http.get<UserDto>(ME_URL)).then(
      (user) => {
        this._user.set(user);
        return user;
      },
      (error: unknown) => {
        if (!(error instanceof HttpErrorResponse && error.status === 401)) {
          this.request = null;
        }
        this._user.set(null);
        return null;
      },
    );
    return this.request;
  }

  async login(input: LoginInput): Promise<UserDto> {
    const user = await firstValueFrom(
      this.http.post<UserDto>('/api/auth/login', input),
    );
    this.setUser(user);
    return user;
  }

  async register(input: RegisterInput): Promise<UserDto> {
    const user = await firstValueFrom(
      this.http.post<UserDto>('/api/auth/register', input),
    );
    this.setUser(user);
    return user;
  }

  async logout(): Promise<void> {
    try {
      await firstValueFrom(this.http.post<void>('/api/auth/logout', null));
    } finally {
      this.clear();
    }
  }

  clear(): void {
    this.setUser(null);
  }

  private setUser(user: UserDto | null): void {
    this._user.set(user);
    this.request = Promise.resolve(user);
  }
}

import { inject } from '@angular/core';
import { type CanActivateFn, Router } from '@angular/router';
import { AuthStore } from './auth.store';

export const authGuard: CanActivateFn = async () => {
  const auth = inject(AuthStore);
  const router = inject(Router);
  const user = await auth.load();
  return user ? true : router.createUrlTree(['/login']);
};

export const adminGuard: CanActivateFn = async () => {
  const auth = inject(AuthStore);
  const router = inject(Router);
  const user = await auth.load();
  return user?.role === 'admin' ? true : router.createUrlTree(['/alerts']);
};

import { HttpErrorResponse, type HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { catchError, throwError } from 'rxjs';
import { AuthStore, ME_URL } from './auth.store';

export const authInterceptor: HttpInterceptorFn = (request, next) => {
  const auth = inject(AuthStore);
  const router = inject(Router);
  return next(request).pipe(
    catchError((error: unknown) => {
      if (
        error instanceof HttpErrorResponse &&
        error.status === 401 &&
        request.url !== ME_URL
      ) {
        auth.clear();
        void router.navigateByUrl('/login');
      }
      return throwError(() => error);
    }),
  );
};

import { HttpErrorResponse } from '@angular/common/http';

// The API sends { statusCode, error, message } for every error.
export function serverMessage(error: unknown): string {
  if (error instanceof HttpErrorResponse) {
    const body: unknown = error.error;
    if (
      typeof body === 'object' &&
      body !== null &&
      'message' in body &&
      typeof body.message === 'string'
    ) {
      return body.message;
    }
    if (error.status === 0) {
      return 'The server cannot be reached. Try again later.';
    }
  }
  return 'Something went wrong. Try again.';
}

// Maps zod issues to one message per top-level field.
export function fieldErrors<K extends string>(
  issues: readonly { path: readonly PropertyKey[] }[],
  messages: Record<K, string>,
): Partial<Record<K, string>> {
  const errors: Partial<Record<K, string>> = {};
  for (const issue of issues) {
    const key = issue.path[0];
    if (typeof key === 'string' && key in messages) {
      errors[key as K] = messages[key as K];
    }
  }
  return errors;
}

