export class TargetsPage {
  private readonly api = inject(TargetsApi);
  private readonly fb = inject(NonNullableFormBuilder);

  protected readonly selectClass = selectClass;
  protected readonly channelOptions = channelIds.map((id) => ({
    id,
    label: channels[id].label,
  }));

  protected readonly targets = signal<TargetDto[] | null>(null);
  protected readonly loadError = signal<string | null>(null);
  protected readonly rows = computed(() =>
    (this.targets() ?? []).map((target) => ({
      target,
      channelLabel: channels[target.channel].label,
      destination: destination(target),
    })),
  );
  protected readonly rowMessages = signal<Record<string, RowMessage>>({});
  protected readonly confirmingDelete = signal<string | null>(null);

  protected readonly form = this.fb.group({
    name: '',
    channel: this.fb.control<ChannelId>(channelIds[0]),
    config: this.fb.record<string>({}),
  });
  protected readonly channel = toSignal(
    this.form.controls.channel.valueChanges,
    { initialValue: this.form.controls.channel.value },
  );
  protected readonly fields = computed<readonly ChannelField[]>(
    () => channels[this.channel()].fields,
  );
  protected readonly errors = signal<Record<string, string>>({});
  protected readonly serverError = signal<string | null>(null);
  protected readonly pending = signal(false);

  constructor() {
    this.resetConfig(this.form.controls.channel.value);
    this.form.controls.channel.valueChanges
      .pipe(takeUntilDestroyed())
      .subscribe((id) => {
        this.resetConfig(id);
        this.errors.set({});
      });
    void this.load();
  }

  protected async sendTest(target: TargetDto): Promise<void> {
    this.setRowMessage(target.id, { tone: 'muted', text: 'Sending' });
    try {
      const result = await this.api.test(target.id);
      this.setRowMessage(
        target.id,
        result.ok
          ? { tone: 'ok', text: 'Sent' }
          : { tone: 'error', text: result.error },
      );
    } catch (error) {
      this.setRowMessage(target.id, {
        tone: 'error',
        text: serverMessage(error),
      });
    }
  }

  protected async remove(target: TargetDto): Promise<void> {
    if (this.confirmingDelete() !== target.id) {
      this.confirmingDelete.set(target.id);
      return;
    }
    this.confirmingDelete.set(null);
    this.setRowMessage(target.id, null);
    try {
      await this.api.remove(target.id);
      this.targets.update(
        (list) => list?.filter((item) => item.id !== target.id) ?? null,
      );
    } catch (error) {
      const text =
        error instanceof HttpErrorResponse && error.status === 409
          ? 'An alert still uses this target.'
          : serverMessage(error);
      this.setRowMessage(target.id, { tone: 'error', text });
    }
  }

  protected cancelDelete(): void {
    this.confirmingDelete.set(null);
  }

  protected async create(): Promise<void> {
    this.serverError.set(null);
    const result = TargetInput.safeParse(this.form.getRawValue());
    if (!result.success) {
      this.errors.set(this.issueMessages(result.error.issues));
      return;
    }
    this.errors.set({});
    this.pending.set(true);
    try {
      const target = await this.api.create(result.data);
      this.targets.update((list) => [target, ...(list ?? [])]);
      this.form.controls.name.reset();
      this.form.controls.config.reset();
    } catch (error) {
      this.serverError.set(serverMessage(error));
    } finally {
      this.pending.set(false);
    }
  }

  private async load(): Promise<void> {
    try {
      this.targets.set(await this.api.list());
    } catch (error) {
      this.loadError.set(serverMessage(error));
    }
  }

  private resetConfig(id: ChannelId): void {
    const config = this.form.controls.config;
    for (const key of Object.keys(config.controls)) {
      config.removeControl(key);
    }
    const fields: readonly ChannelField[] = channels[id].fields;
    for (const field of fields) {
      config.addControl(field.key, this.fb.control(''));
    }
  }

  private issueMessages(
    issues: readonly { path: readonly PropertyKey[] }[],
  ): Record<string, string> {
    const messages: Record<string, string> = {};
    for (const [first, second] of issues.map((issue) => issue.path)) {
      if (first === 'name') {
        messages['name'] = `Enter a name of up to ${LIMITS.name} characters.`;
      } else if (first === 'config' && typeof second === 'string') {
        const label =
          this.fields().find((field) => field.key === second)?.label ?? second;
        messages[`config.${second}`] = `${label} is not valid.`;
      }
    }
    return messages;
  }

  private setRowMessage(id: string, message: RowMessage | null): void {
    this.rowMessages.update((messages) => {
      const next = { ...messages };
      if (message) {
        next[id] = message;
      } else {
        delete next[id];
      }
      return next;
    });
  }

import {
  DisasterType,
  LIMITS,
  Region,
  type AlertDto,
  type AlertInput,
  type Category,
  type MarketDirection,
} from '@alerts/shared';
import { fieldErrors } from '../core/errors';

export const categoryLabels: Record<Category, string> = {
  news: 'News',
  market: 'Market',
  disaster: 'Disaster',
};

export const directionLabels: Record<MarketDirection, string> = {
  any: 'Any',
  up: 'Up',
  down: 'Down',
};

export const disasterTypeLabels: Record<DisasterType, string> = {
  earthquake: 'Earthquake',
  flood: 'Flood',
  storm: 'Storm',
  wildfire: 'Wildfire',
};

export const regionLabels: Record<Region, string> = {
  africa: 'Africa',
  asia: 'Asia',
  europe: 'Europe',
  'north-america': 'North America',
  'south-america': 'South America',
  oceania: 'Oceania',
};

// The raw value of the alert form. Lists are comma-separated text or one flag per option.
export interface AlertFormValue {
  name: string;
  category: Category;
  news: { keywords: string };
  market: {
    symbols: string;
    direction: MarketDirection;
    minChangePct: number | null;
  };
  disaster: {
    types: Record<DisasterType, boolean>;
    regions: Record<Region, boolean>;
    minMagnitude: number | null;
  };
  minSeverity: number;
  targets: Record<string, boolean>;
  enabled: boolean;
}

function flags<K extends string>(
  options: readonly K[],
  selected: readonly K[],
): Record<K, boolean> {
  return Object.fromEntries(
    options.map((option) => [option, selected.includes(option)]),
  ) as Record<K, boolean>;
}

function splitList(text: string): string[] {
  return text
    .split(',')
    .map((item) => item.trim())
    .filter((item) => item !== '');
}

export function emptyAlertForm(): AlertFormValue {
  return {
    name: '',
    category: 'news',
    news: { keywords: '' },
    market: { symbols: '', direction: 'any', minChangePct: 0 },
    disaster: {
      types: flags(DisasterType.options, []),
      regions: flags(Region.options, []),
      minMagnitude: null,
    },
    minSeverity: 1,
    targets: {},
    enabled: true,
  };
}

// The result still needs AlertInput.safeParse, which reports the fields the user has to fix.
export function toAlertInput(value: AlertFormValue): AlertInput {
  const base = {
    name: value.name,
    minSeverity: value.minSeverity,
    targetIds: Object.keys(value.targets).filter((id) => value.targets[id]),
    enabled: value.enabled,
  };
  switch (value.category) {
    case 'news':
      return {
        ...base,
        category: 'news',
        filters: { keywords: splitList(value.news.keywords) },
      };
    case 'market':
      return {
        ...base,
        category: 'market',
        filters: {
          symbols: splitList(value.market.symbols),
          direction: value.market.direction,
          minChangePct: value.market.minChangePct ?? 0,
        },
      };
    case 'disaster': {
      const { types, regions, minMagnitude } = value.disaster;
      return {
        ...base,
        category: 'disaster',
        filters: {
          types: DisasterType.options.filter((type) => types[type]),
          regions: Region.options.filter((region) => regions[region]),
          ...(minMagnitude === null ? {} : { minMagnitude }),
        },
      };
    }
  }
}

export function fromAlertDto(alert: AlertDto): AlertFormValue {
  const value: AlertFormValue = {
    ...emptyAlertForm(),
    name: alert.name,
    category: alert.category,
    minSeverity: alert.minSeverity,
    targets: Object.fromEntries(alert.targetIds.map((id) => [id, true])),
    enabled: alert.enabled,
  };
  switch (alert.category) {
    case 'news':
      value.news = { keywords: alert.filters.keywords.join(', ') };
      break;
    case 'market':
      value.market = {
        symbols: alert.filters.symbols.join(', '),
        direction: alert.filters.direction,
        minChangePct: alert.filters.minChangePct,
      };
      break;
    case 'disaster':
      value.disaster = {
        types: flags(DisasterType.options, alert.filters.types),
        regions: flags(Region.options, alert.filters.regions),
        minMagnitude: alert.filters.minMagnitude ?? null,
      };
      break;
  }
  return value;
}

const errorMessages = {
  name: `Enter a name of up to ${LIMITS.name} characters.`,
  keywords: `Enter up to ${LIMITS.keywords} keywords of at most ${LIMITS.keyword} characters each.`,
  symbols: `Enter up to ${LIMITS.symbols} symbols of at most ${LIMITS.symbol} characters each.`,
  direction: 'Choose a direction.',
  minChangePct: 'Enter a change of 0 or more.',
  types: 'Choose from the listed types.',
  regions: 'Choose from the listed regions.',
  minMagnitude: 'Enter a number or leave the field empty.',
  minSeverity: 'Choose a severity from 1 to 5.',
  targetIds: `Choose from 1 to ${LIMITS.targetIds} targets.`,
};

export type AlertErrors = Partial<Record<keyof typeof errorMessages, string>>;

// Filter issues sit under filters.<key>, so the filters prefix is dropped to key them by field.
export function alertErrors(
  issues: readonly { path: readonly PropertyKey[] }[],
): AlertErrors {
  return fieldErrors(
    issues.map(({ path }) => ({
      path: path[0] === 'filters' ? path.slice(1) : path,
    })),
    errorMessages,
  );
}

export function summarizeFilters(alert: AlertInput): string {
  switch (alert.category) {
    case 'news': {
      const { keywords } = alert.filters;
      return keywords.length > 0
        ? `Keywords: ${keywords.join(', ')}`
        : 'Any news';
    }
    case 'market': {
      const { symbols, direction, minChangePct } = alert.filters;
      return [
        symbols.length > 0 ? symbols.join(', ') : 'Any symbol',
        direction === 'any' ? 'up or down' : direction,
        `${minChangePct}% or more`,
      ].join(' · ');
    }
    case 'disaster': {
      const { types, regions, minMagnitude } = alert.filters;
      const parts = [
        types.length > 0
          ? types.map((type) => disasterTypeLabels[type]).join(', ')
          : 'Any type',
        regions.length > 0
          ? regions.map((region) => regionLabels[region]).join(', ')
          : 'any region',
      ];
      if (minMagnitude !== undefined) {
        parts.push(`earthquakes from magnitude ${minMagnitude}`);
      }
      return parts.join(' · ');
    }
  }
}

