import type { Role } from '@alerts/shared';
import { hashPassword } from '../auth/password';
import { loadConfig, loadRootEnvFile } from '../config';
import { safeErrorLog } from '../safe-error-log';
import { createDb, type Db } from './client';
import { users } from './schema';

async function ensureUser(
  db: Db,
  email: string,
  password: string,
  role: Role,
): Promise<void> {
  const inserted = await db
    .insert(users)
    .values({ email, passwordHash: await hashPassword(password), role })
    .onConflictDoNothing({ target: users.email })
    .returning({ id: users.id });
  console.log(
    inserted.length > 0
      ? `Created ${role} ${email}.`
      : `${email} already exists, left unchanged.`,
  );
}

async function main(): Promise<void> {
  loadRootEnvFile();
  const config = loadConfig(process.env);
  const { db, pool } = createDb(config.DATABASE_URL);
  try {
    await ensureUser(
      db,
      config.SEED_ADMIN_EMAIL,
      config.SEED_ADMIN_PASSWORD,
      'admin',
    );
    await ensureUser(
      db,
      config.SEED_USER_EMAIL,
      config.SEED_USER_PASSWORD,
      'user',
    );
  } finally {
    await pool.end();
  }
}

main().catch((error: unknown) => {
  console.error('Seeding failed:', safeErrorLog(error));
  process.exitCode = 1;
});
import type { Category, ChannelId } from '@alerts/shared';
import type { Db } from './client';
import { channels, sources } from './schema';

export interface RegistryRows {
  channelIds: readonly ChannelId[];
  sources: readonly { id: string; category: Category }[];
}

// "On conflict do nothing" keeps every switch the admin has already set.
export async function syncRegistryRows(
  db: Db,
  registry: RegistryRows,
): Promise<void> {
  if (registry.channelIds.length > 0) {
    await db
      .insert(channels)
      .values(registry.channelIds.map((id) => ({ id, enabled: true })))
      .onConflictDoNothing();
  }
  if (registry.sources.length > 0) {
    await db
      .insert(sources)
      .values(
        registry.sources.map(({ id, category }) => ({
          id,
          category,
          enabled: true,
        })),
      )
      .onConflictDoNothing();
  }
}
import { randomUUID } from 'node:crypto';
import type { FastifyInstance } from 'fastify';
import {
  EventInput,
  HookIdParam,
  MockSlackMessage,
  MockSlackMode,
  type DevEventResult,
} from '@alerts/shared';
import { ingestEvent, toEventDto } from '../events/ingest';
import { HttpError } from '../http-error';

export const MOCK_SLACK_MAX_MESSAGES = 500;

interface ReceivedSlackMessage {
  hookId: string;
  text: string;
  receivedAt: string;
}

// buildApp registers these only outside production, so they need no login.
export async function devRoutes(app: FastifyInstance): Promise<void> {
  // Newest first. Each app instance has its own store.
  const slackMessages: ReceivedSlackMessage[] = [];
  let slackFails = false;

  app.post('/events', async (request, reply): Promise<DevEventResult> => {
    const input = EventInput.parse(request.body);
    const result = await ingestEvent(app.db, {
      ...input,
      sourceId: 'dev',
      externalId: randomUUID(),
    });
    if (!result) {
      throw new HttpError(409, 'Event already exists');
    }
    reply.code(201);
    return {
      event: toEventDto(result.event),
      deliveriesCreated: result.deliveriesCreated,
    };
  });

  app.post('/mock-slack/:hookId', async (request, reply) => {
    const { hookId } = HookIdParam.parse(request.params);
    const { text } = MockSlackMessage.parse(request.body);
    slackMessages.unshift({
      hookId,
      text,
      receivedAt: new Date().toISOString(),
    });
    slackMessages.splice(MOCK_SLACK_MAX_MESSAGES);
    if (slackFails) {
      return reply.code(500).send({
        statusCode: 500,
        error: 'Internal Server Error',
        message: 'Mock Slack fail mode is on',
      });
    }
    // Slack answers a successful webhook call with the plain text "ok".
    return 'ok';
  });

  app.get('/mock-slack/messages', async () => slackMessages);

  app.delete('/mock-slack/messages', async (_request, reply) => {
    slackMessages.length = 0;
    return reply.code(204).send();
  });

  app.put('/mock-slack/mode', async (request) => {
    const { fail } = MockSlackMode.parse(request.body);
    slackFails = fail;
    return { fail };
  });
}
